def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    my_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
        if history[i][0] == 'D':
            my_d += 1
    opp_c = n - opp_d

    # Endgame: exploit known cooperativeness.
    if n >= 100:
        return 'D' if opp_c > opp_d else 'C'
    if n >= 98:
        if opp_c >= 90:
            return 'D'
        return 'D' if opp_c > opp_d else 'C'
    if n >= 95:
        if opp_c * 10 >= n * 7:
            return 'D'
        return 'D' if opp_c > opp_d else 'C'

    # Identify always-defectors and punish hard.
    if n >= 6 and opp_d == n:
        return 'D'

    # Early probing: cooperate but occasionally test.
    if n < 5:
        return 'C'

    # Detect a sustained long defection streak by opponent.
    if n >= 3:
        if history[-1][1] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
            return 'D'

    # Recent window analysis (last 8).
    w = 8 if n >= 8 else n
    rec_opp_d = 0
    rec_opp_c = 0
    rec_my_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1
        if history[i][0] == 'D':
            rec_my_d += 1

    last_me, last_opp = history[-1]

    # Mostly-cooperative opponent: lean cooperate, probe occasionally.
    if opp_c * 100 >= n * 90 and n >= 12:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Very defection-heavy opponent: defend.
    if opp_d * 100 >= n * 75 and n >= 8:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # If opponent has just cooperated after defecting, forgive to reestablish CC.
    if last_opp == 'C' and n >= 2 and history[-2][1] == 'D' and rec_opp_d <= 2:
        return 'C'

    # Tit-for-tat core on most recent opponent action, with mild forgiveness.
    if last_opp == 'D':
        # Forgive if opponent is generally cooperative and streak is short.
        if rec_opp_d == 1 and opp_c * 100 >= n * 75:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Two defections in a row: retaliate but avoid lock-in.
        if rec_opp_d == 2 and rec_my_d >= 1:
            return 'D'
        if rec_opp_d >= 3:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    # If we've been defecting a lot and they remain cooperative, exploit more.
    if my_d > opp_d + 2 and n >= 15 and opp_c * 100 >= n * 70:
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Punish if we've been heavily exploited on overall scores.
    my_score = 0
    opp_score = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1
    if opp_score > my_score + 12 and n >= 20:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    return 'C'
